import six

from SSHLibrary import SSHClient
from robot.utils.robottime import timestr_to_secs

from ute_common_store import Store
from ute_common_converter.to_number import to_int
from ute_common_converter.to_bool import to_bool
from ute_common_interface.scope import ScopeController

from ..wts.egate import Egate
from ..wts.edaemon import Edaemon
from ..interactor.notifier import Notifier
from ..client.telnetclient import TelnetClient
from ..utils.settings import ConnectionSettings


class WTSCommonInterface(ScopeController):
    def __init__(self):
        super(WTSCommonInterface, self).__init__()
        self.egate_store = Store()
        self.wts_store = Store()
        self.edaemon_store = Store()
        self.notifier = Notifier()
        self.connection_settings = {}

    def _configure_ssh_connection(self, host_ip, ssh_username, ssh_password, ssh_port, ssh_prompt):
        connection_settings = ConnectionSettings()
        connection_settings.host_ip = host_ip
        connection_settings.ssh_username = ssh_username
        connection_settings.ssh_password = ssh_password
        connection_settings.ssh_port = to_int(ssh_port, skip_none=True)
        connection_settings.ssh_prompt = ssh_prompt
        return connection_settings

    def _configure_ssh_connection_for_alias(self, host_ip, ssh_username, ssh_password, ssh_port, ssh_prompt, alias):
        self.connection_settings[alias] = self._configure_ssh_connection(host_ip, ssh_username, ssh_password, ssh_port, ssh_prompt)

    def _configure_ssh_connection_to_enb(self, enb_ip, enb_username, enb_password, enb_prompt, alias):
        settings = self._get_connection_settings_for_alias(alias)
        settings.enb_ip = enb_ip
        settings.enb_username = enb_username
        settings.enb_password = enb_password
        settings.enb_prompt = enb_prompt

    def _init_connection_parameters(self, alias):
        self.connection_settings[alias] = ConnectionSettings()

    def _to_secs(self, value):
        if value is None:
            return None
        return timestr_to_secs(value)

    def _create_ssh_client_from_settings(self, settings):
        client = SSHClient(**settings.ssh_connection_params)
        if ('look_for_keys' in client.login.__code__.co_varnames):
            client.login(look_for_keys=True, **settings.ssh_login_params)
        else:
            client.login(**settings.ssh_login_params)
        return client

    def _get_connection_settings_for_alias(self, alias):
        if alias in self.connection_settings:
            settings = self.connection_settings[alias]
        else:
            settings = ConnectionSettings()
            self.connection_settings[alias] = settings
        return settings

    def _create_ssh_client_for_alias(self, alias):
        settings = self._get_connection_settings_for_alias(alias)
        return self._create_ssh_client_from_settings(settings)

    def _create_telnet_client_from_settings(self, settings, port):
        settings.telnet_port = to_int(port, skip_none=True)
        return TelnetClient(**settings.telnet_params)

    def _create_telnet_client_for_alias(self, port, alias):
        settings = self._get_connection_settings_for_alias(alias)
        return self._create_telnet_client_from_settings(settings, port)

    def _notify_extenders(self, egate, alias, extenders):
        if isinstance(extenders, six.string_types):
            extenders = [extenders]
        self.notifier.egate_created(egate, alias, *extenders)

    def _create_egate(self, port, ssh_client, telnet_client, tool_dir, lua_dirs=()):
        egate = Egate(ssh_client=ssh_client, telnet=telnet_client, port=to_int(port))
        egate.tool_dir = tool_dir
        for each in lua_dirs:
            egate.lua_dirs.append(each)
        return egate

    def _create_edaemons(self, ports, ssh_client, tool_dir):
        edaemons = []
        for index, port in enumerate(ports):
            edaemon = Edaemon(ssh_client=ssh_client, port=to_int(port))
            edaemon.tool_dir = tool_dir
            edaemons.append(edaemon)
        return edaemons

    def _collect_logs(self, wts, unzip, subdirectory):
        subdirectory = None if subdirectory is None else str(subdirectory)
        if wts.edaemons:
            files_list = ["'{}'/edaemon.log", "'{}'/edaemon.log.*", "'{}'/mme_*.log.*", "'{}'/pgw_*.log.*", "'{}'/sgw_*.log.*", "'{}'/uec_*.log.*",
                          "'{}'/enb_*.log.*"]
            wts.get_edaemons_logs(files_list, to_bool(unzip, skip_none=True), subdirectory)
        if wts.egates:
            files_list = ["'{}'/egate.log*", "'{}'/egate_console.log*"]

            wts.get_egates_logs(files_list, to_bool(unzip, skip_none=True), subdirectory)
